tool_input.command:
$targetRef = 'origin/suzhou-taicang-wuguan-dev-v1.26'
$bootstrap = git -C 'D:\repository\太仓物管后端' show "${targetRef}:zhishu-company/src/main/resources/bootstrap.yml" 2>$null
if ($LASTEXITCODE -ne 0) { 'BOOTSTRAP_READ_FAILED'; exit 2 }
$userMatch = [regex]::Match(($bootstrap -join "`n"), '(?im)^\s*username:\s*["'']?([^"''#\s]+)')
$passMatch = [regex]::Match(($bootstrap -join "`n"), '(?im)^\s*password:\s*["'']?([^"''#\s]+)')
if (-not $userMatch.Success -or -not $passMatch.Success) { 'NACOS_CREDENTIAL_KEYS_NOT_FOUND'; exit 3 }
$loginUri = 'http://192.168.1.12:8848/nacos/v1/auth/login'
try {
  $auth = Invoke-RestMethod -Uri $loginUri -Method Post -Body @{ username = $userMatch.Groups[1].Value; password = $passMatch.Groups[1].Value } -TimeoutSec 15
  $accessToken = if ($auth.accessToken) { $auth.accessToken } elseif ($auth.token) { $auth.token } else { '' }
  $cfgUri = 'http://192.168.1.12:8848/nacos/v1/cs/configs?dataId=shared-druid-dev.yml&group=DEFAULT_GROUP&tenant=zscloud'
  if ($accessToken) { $cfgUri += '&accessToken=' + [uri]::EscapeDataString($accessToken) }
  $cfg = Invoke-RestMethod -Uri $cfgUri -Method Get -TimeoutSec 15
  $content = [string]$cfg
  $url = [regex]::Match($content, '(?im)^\s*url:\s*["'']?([^"''\r\n]+)')
  $driver = [regex]::Match($content, '(?im)^\s*driver-class-name:\s*["'']?([^"''\r\n]+)')
  $username = [regex]::Match($content, '(?im)^\s*username:\s*["'']?([^"''\r\n]+)')
  if (-not $url.Success) { 'NACOS_CONFIG_FETCHED; URL_FIELD_NOT_FOUND'; exit 4 }
  $safeUrl = $url.Groups[1].Value -replace '://[^/@]+:[^/@]+@','://[redacted]@'
  $safeUrl = $safeUrl -replace '(?i)(password|pwd)=([^;&]+)','$1=[redacted]'
  'NACOS_CONFIG_FETCHED'
  'URL=' + $safeUrl
  if ($driver.Success) { 'DRIVER=' + $driver.Groups[1].Value }
  if ($username.Success) { 'DB_USERNAME=' + $username.Groups[1].Value }
  'DB_PASSWORD_PRESENT=' + [bool]([regex]::IsMatch($content, '(?im)^\s*password:\s*\S+'))
} catch {
  'NACOS_READ_FAILED; TYPE=' + $_.Exception.GetType().Name
}
